system_a_kql:
let TimeWindow = 1h;
let ExportCmd = "New-MailboxExportRequest";
let RemoveCmd = "Remove-MailboxExportRequest";
let Exports = SecurityEvent
| where CommandLine has ExportCmd
| project Host = DvcHostname, User = ActorUsername, TimeGenerated;
let Removes = SecurityEvent
| where CommandLine has RemoveCmd
| project Host = DvcHostname, User = ActorUsername, TimeGenerated;
Exports
| join kind=inner (Removes) on Host, User
| where Removes.TimeGenerated between (Exports.TimeGenerated .. Exports.TimeGenerated + TimeWindow)
| project Host, User, ExportTime = Exports.TimeGenerated, RemoveTime = Removes.TimeGenerated, ExportCommand = ExportCmd, RemoveCommand = RemoveCmd

let TimeRange = 3d;
let FirstSeenProcesses = 
    SecurityEvent
    | where TimeGenerated >= ago(TimeRange)
    | summarize FirstSeen=min(TimeGenerated) by ProcessName=ActingProcessName, DvcHostname;
FirstSeenProcesses
| summarize CountHosts=dcount(DvcHostname) by ProcessName, FirstSeen
| sort by CountHosts asc, FirstSeen asc
| where CountHosts == 1
| project ProcessName, FirstSeen, CountHosts

let lookback = 3d;
let percentile_threshold = 5;
let exclude_patterns = dynamic(@'["^msiexec.*", "^setup.*", "^install.*", "^tmp.*", "^temp.*", "^~.*"]');
DeviceProcessEvents
| where TimeGenerated >= ago(lookback)
| where not(ActingProcessName matches regex strcat_array(exclude_patterns, "|"))
| summarize ExecutionCount = count() by ActingProcessName
| summarize PercentileValue = percentile(ExecutionCount, percentile_threshold)
| where ExecutionCount <= PercentileValue
| project ActingProcessName, ExecutionCount

