| where NetworkProtocol == "SMB"
| summarize Count = count() by SrcIpAddr, bin(TimeGenerated, 1d);
let Stats = SMBConnections
| summarize AvgCount = avg(Count), StdevCount = stdev(Count) by SrcIpAddr;
