| where TimeGenerated > ago(TimeWindow)
| join kind=inner Stats on SrcIpAddr
| extend Deviation = abs(Count - AvgCount) / StdevCount
| where Deviation > Threshold
| project SrcIpAddr, TimeGenerated, Count, AvgCount, StdevCount, Deviation

