system_a_kql:
let baselineStart = ago(15d);
let baselineEnd = ago(1d);
let recentStart = ago(1d);
let recentEnd = now();
let privateIpRange = (ip: string) {
    ipmatches(ip, "10.0.0.0/8") or ipmatches(ip, "172.16.0.0/12") or ipmatches(ip, "192.168.0.0/16")
};
let baseline = network_session
| where TimeGenerated between (baselineStart .. baselineEnd)
| where DstPortNumber in (139, 445)
| where privateIpRange(SrcIpAddr)
| summarize BaselineAvg = avg(count_) by SrcIpAddr, SrcPortNumber = SrcPortNumber
| extend SrcPortNumber = tostring(SrcPortNumber);
let recent = network_session
| where TimeGenerated between (recentStart .. recentEnd)
| where DstPortNumber in (139, 445)
| where privateIpRange(SrcIpAddr)
| summarize RecentCount = count() by SrcIpAddr, SrcPortNumber = SrcPortNumber
| extend SrcPortNumber = tostring(SrcPortNumber);
recent
| join kind=inner baseline on SrcIpAddr, SrcPortNumber
| where RecentCount > BaselineAvg + 50
| project SrcIpAddr, SrcPortNumber, RecentCount, BaselineAvg

